import re
try:
    b = config.get('body')
    if isinstance(b, dict):
        a = str(b.get('answer') or '').strip()
        if b.get('field') == 'phone_last4':
            dg = re.sub('[^0-9]', '', a)
            if len(dg) >= 4:
                dg = dg[-4:]
            b['answer'] = dg
        else:
            m = re.match('^([0-9]{1,2})[./ -]([0-9]{1,2})[./ -]([0-9]{4})$', a)
            if m:
                b['answer'] = m.group(3) + '-' + m.group(2).zfill(2) + '-' + m.group(1).zfill(2)
            else:
                b['answer'] = a
except Exception:
    pass

